create extension if not exists "pgcrypto";
create table profiles(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,full_name text not null,phone text,created_at timestamptz default now(),updated_at timestamptz default now());
create table businesses(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null,category text,phone text,whatsapp_number text,email text,state text,city text,address text,logo_url text,currency text not null default 'NGN',created_at timestamptz default now(),updated_at timestamptz default now());
create table customers(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,name text not null,phone text,whatsapp_number text,email text,address text,city text,state text,notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table products(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,name text not null,description text,sku text,price numeric(12,2) not null check(price>=0),image_url text,active boolean not null default true,stock_quantity integer default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create type order_status as enum('New','Awaiting Payment','Paid','Processing','Ready','Shipped','Delivered','Cancelled');create type payment_status as enum('Unpaid','Partial','Paid');create type payment_method as enum('Bank Transfer','Cash','POS','Other');
create table orders(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,customer_id uuid not null references customers(id),order_number text not null,status order_status not null default 'New',subtotal numeric(12,2) not null default 0,delivery_fee numeric(12,2) not null default 0,discount numeric(12,2) not null default 0,total numeric(12,2) not null default 0,payment_status payment_status not null default 'Unpaid',payment_method payment_method not null default 'Bank Transfer',notes text,created_at timestamptz default now(),updated_at timestamptz default now(),unique(business_id,order_number));
create table order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id) on delete cascade,product_id uuid references products(id),product_name text not null,quantity integer not null check(quantity>0),unit_price numeric(12,2) not null,total_price numeric(12,2) not null);
alter table profiles enable row level security;alter table businesses enable row level security;alter table customers enable row level security;alter table products enable row level security;alter table orders enable row level security;alter table order_items enable row level security;
create policy profiles_own on profiles for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy businesses_own on businesses for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy customers_business on customers for all using(exists(select 1 from businesses b where b.id=business_id and b.owner_id=auth.uid())) with check(exists(select 1 from businesses b where b.id=business_id and b.owner_id=auth.uid()));
create policy products_business on products for all using(exists(select 1 from businesses b where b.id=business_id and b.owner_id=auth.uid())) with check(exists(select 1 from businesses b where b.id=business_id and b.owner_id=auth.uid()));
create policy orders_business on orders for all using(exists(select 1 from businesses b where b.id=business_id and b.owner_id=auth.uid())) with check(exists(select 1 from businesses b where b.id=business_id and b.owner_id=auth.uid()));
create policy items_business on order_items for all using(exists(select 1 from orders o join businesses b on b.id=o.business_id where o.id=order_id and b.owner_id=auth.uid())) with check(exists(select 1 from orders o join businesses b on b.id=o.business_id where o.id=order_id and b.owner_id=auth.uid()));
